package com.comandos.reservation.service;
import com.comandos.audit.service.AuditService;import com.comandos.core.model.*;import com.comandos.inventory.model.*;import com.comandos.reservation.dto.ReservationContract.*;import com.comandos.reservation.model.*;import com.comandos.security.service.AccessPolicy;import jakarta.persistence.*;import java.math.*;import java.nio.charset.StandardCharsets;import java.security.*;import java.time.*;import java.util.*;import org.springframework.http.*;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import org.springframework.web.server.ResponseStatusException;
@Service@Transactional(readOnly=true)public class ReservationService{
 private final EntityManager em;private final AccessPolicy access;private final AuditService audit;public ReservationService(EntityManager em,AccessPolicy access,AuditService audit){this.em=em;this.access=access;this.audit=audit;}
 public Page<StockOption>stock(long org,Long unit,String kind,String search){access.requireScope("reservations","READ",org,unit);selectedUnit(org,unit);boolean assets="ASSET".equals(kind);if(!assets&&!"LOT".equals(kind))bad("Stock kind must be ASSET or LOT.");String model=assets?"e.model":"e.lot.model",code=assets?"e.assetCode":"e.lot.lotNumber";String from=" from "+(assets?"AssetItem":"StockBalance")+" e where e.location.organization.id=:o"+(unit==null?"":" and e.location.unit.id=:u")+(assets?" and e.status='AVAILABLE'":" and e.available>0")+" and ("+(assets?"e.validUntil":"e.lot.validUntil")+" is null or "+(assets?"e.validUntil":"e.lot.validUntil")+">=:today) and (lower("+code+") like :s escape '!' or lower("+model+".name) like :s escape '!' or lower("+model+".sku) like :s escape '!')";var q=em.createQuery("select e"+from+" order by e.id",CoreEntity.class);var c=em.createQuery("select count(e)"+from,Long.class);for(Query x:List.of(q,c)){x.setParameter("o",org).setParameter("today",LocalDate.now()).setParameter("s",term(search));if(unit!=null)x.setParameter("u",unit);}return new Page<>(q.setMaxResults(20).getResultList().stream().map(e->{if(e instanceof AssetItem a)return new StockOption("ASSET",a.id,a.assetCode,a.model.name,a.model.sku,a.location.name,a.model.unitOfMeasure,"1");var b=(StockBalance)e;return new StockOption("LOT",b.id,b.lot.lotNumber,b.lot.model.name,b.lot.model.sku,b.location.name,b.lot.model.unitOfMeasure,decimal(b.available));}).toList(),c.getSingleResult(),0,20);}
 @Transactional public ReservationView create(CreateRequest r){validate(r);access.requireScope("reservations","CREATE",r.organizationId(),r.unitId());lockCatalog();var o=locked(Organization.class,r.organizationId());if(!o.active)bad("Organization must be active.");var u=selectedUnit(o.id,r.unitId());String fp=fingerprint(r);var existing=em.createQuery("select r from InventoryReservation r where r.requestId=:id",InventoryReservation.class).setParameter("id",r.requestId()).getResultStream().findFirst();if(existing.isPresent()){access.requireEntity("reservations","READ",existing.get());if(!existing.get().requestFingerprint.equals(fp))conflict("Request ID already used for another reservation.");return view(existing.get());}var status=status("ACTIVE");if(!status.active)bad("The ACTIVE reservation status is inactive.");var reservation=new InventoryReservation();reservation.organization=o;reservation.unit=u;reservation.status=status;reservation.organizationName=o.name;reservation.unitName=u==null?null:u.name;reservation.purpose=r.purpose().trim();reservation.startsAt=parse(r.startsAt());reservation.endsAt=parse(r.endsAt());reservation.createdOn=LocalDateTime.now();var actor=audit.actor();reservation.operatorId=actor.id();reservation.operatorLogin=actor.login();reservation.requestId=r.requestId();reservation.requestFingerprint=fp;em.persist(reservation);List<Map<String,Object>>changes=new ArrayList<>();for(var line:sorted(r.items()))reserve(reservation,line,changes);em.flush();var result=view(reservation);audit.record("reservations",reservation.id,"CREATE",null,Map.of("reservation",result,"stockChanges",changes));return result;}
 @Transactional public ReservationView release(long id,String code){var r=locked(InventoryReservation.class,id);access.requireEntity("reservations","EXPIRED".equals(code)?"EXPIRE":"CANCEL",r);if(!"ACTIVE".equals(r.status.code))return view(r);if("EXPIRED".equals(code)&&r.endsAt.isAfter(LocalDateTime.now()))bad("A reservation cannot expire before its end date.");r.status=status(code);r.releasedAt=LocalDateTime.now();List<Map<String,Object>>changes=new ArrayList<>();for(var item:items(r.id)){if(item.asset!=null){String before=item.asset.status;if(AssetStatus.BLOCKED.name().equals(before)&&canRelease(item.asset))item.asset.status=AssetStatus.AVAILABLE.name();changes.add(Map.of("resource","inventory/assets","recordId",item.asset.id,"before",before,"after",item.asset.status));}else{var b=locked(StockBalance.class,item.balance.id);if(b.reserved.compareTo(item.quantity)<0)conflict("Reserved balance is inconsistent.");b.reserved=b.reserved.subtract(item.quantity);b.available=b.available.add(item.quantity);changes.add(Map.of("resource","inventory/balances","recordId",b.id,"released",decimal(item.quantity)));}}em.flush();var result=view(r);audit.record("reservations",r.id,code,null,Map.of("reservation",result,"stockChanges",changes));return result;}
 public Page<ReservationView>list(long org,Long unit,int page){access.requireScope("reservations","READ",org,unit);selectedUnit(org,unit);if(page<0)bad("Invalid page.");String f=" from InventoryReservation r where r.organization.id=:o"+(unit==null?"":" and r.unit.id=:u");var q=em.createQuery("select r"+f+" order by r.id desc",InventoryReservation.class);var c=em.createQuery("select count(r)"+f,Long.class);q.setParameter("o",org);c.setParameter("o",org);if(unit!=null){q.setParameter("u",unit);c.setParameter("u",unit);}return new Page<>(q.setFirstResult(page*20).setMaxResults(20).getResultList().stream().map(this::view).toList(),c.getSingleResult(),page,20);}
 private void reserve(InventoryReservation r,LineRequest line,List<Map<String,Object>>changes){var item=new ReservationItem();item.reservation=r;item.quantity=line.quantity();if(line.assetId()!=null){var a=locked(AssetItem.class,line.assetId());scope(a.location,r);if(!AssetStatus.AVAILABLE.name().equals(a.status))conflict("Asset "+a.assetCode+" is no longer available.");notExpired(a.validUntil);if(line.quantity().compareTo(BigDecimal.ONE)!=0)bad("Individual assets require quantity 1.");item.asset=a;item.model=a.model;item.location=a.location;item.stockCode=a.assetCode;changes.add(Map.of("resource","inventory/assets","recordId",a.id,"before",AssetStatus.AVAILABLE.name(),"after",AssetStatus.BLOCKED.name()));a.status=AssetStatus.BLOCKED.name();}else{var b=locked(StockBalance.class,line.balanceId());scope(b.location,r);var l=locked(StockLot.class,b.lot.id);notExpired(l.validUntil);if(b.available.compareTo(line.quantity())<0)conflict("Insufficient available stock for lot "+l.lotNumber+".");item.balance=b;item.lot=l;item.model=l.model;item.location=b.location;item.stockCode=l.lotNumber;b.available=b.available.subtract(line.quantity());b.reserved=b.reserved.add(line.quantity());changes.add(Map.of("resource","inventory/balances","recordId",b.id,"reserved",decimal(line.quantity())));}item.modelName=item.model.name;item.sku=item.model.sku;item.locationName=item.location.name;item.unitOfMeasure=item.model.unitOfMeasure;em.persist(item);}
 private boolean canRelease(AssetItem a){if(a.validUntil!=null&&a.validUntil.isBefore(LocalDate.now()))return false;long recalls=em.createQuery("select count(i) from RecallItem i where i.asset.id=:a and i.recall.status in ('OPEN','IN_PROGRESS')",Long.class).setParameter("a",a.id).getSingleResult();long expired=em.createQuery("select count(e) from ExpirationRecord e where e.asset.id=:a and e.status='EXPIRED'",Long.class).setParameter("a",a.id).getSingleResult();long missing=em.createQuery("select count(i) from InventoryCountItem i where i.asset.id=:a and i.inventoryCount.status.code='APPROVED' and i.result.code='SHORTAGE'",Long.class).setParameter("a",a.id).getSingleResult();return recalls+expired+missing==0;}
 private ReservationView view(InventoryReservation r){var lines=items(r.id).stream().map(i->new LineView(i.id,i.asset==null?null:i.asset.id,i.lot==null?null:i.lot.id,i.modelName,i.sku,i.stockCode,i.locationName,i.unitOfMeasure,decimal(i.quantity))).toList();return new ReservationView(r.id,r.organization.id,r.organizationName,r.unit==null?null:r.unit.id,r.unitName,r.purpose,r.startsAt.toString(),r.endsAt.toString(),r.status.code,r.status.name,r.createdOn.toString(),r.releasedAt==null?null:r.releasedAt.toString(),r.operatorLogin,lines);}private List<ReservationItem>items(long id){return em.createQuery("select i from ReservationItem i where i.reservation.id=:id order by i.id",ReservationItem.class).setParameter("id",id).getResultList();}
 private ReservationStatusType status(String code){return em.createQuery("select s from ReservationStatusType s where s.code=:c",ReservationStatusType.class).setParameter("c",code).setLockMode(LockModeType.PESSIMISTIC_WRITE).getResultStream().findFirst().orElseThrow(()->new ResponseStatusException(HttpStatus.CONFLICT,"Required reservation status "+code+" is not configured."));}private void scope(StockLocation l,InventoryReservation r){access.requireScope("reservations","CREATE",l.organization.id,l.unit==null?null:l.unit.id);if(!l.organization.id.equals(r.organization.id)||r.unit!=null&&(l.unit==null||!l.unit.id.equals(r.unit.id)))bad("Every item must belong to the selected scope.");}
 private void validate(CreateRequest r){if(r==null||r.organizationId()==null||blank(r.purpose())||blank(r.startsAt())||blank(r.endsAt()))bad("Organization, purpose, start and end are required.");uuid(r.requestId());var start=parse(r.startsAt());var end=parse(r.endsAt());if(!end.isAfter(start)||!end.isAfter(LocalDateTime.now()))bad("Reservation end must be after its start and in the future.");if(r.items()==null||r.items().isEmpty()||r.items().size()>100)bad("A reservation requires 1 to 100 items.");Set<String>keys=new HashSet<>();for(var i:r.items()){if(i==null||(i.assetId()==null)==(i.balanceId()==null))bad("Select exactly one asset or balance.");amount(i.quantity());if(!keys.add(i.assetId()!=null?"A"+i.assetId():"B"+i.balanceId()))bad("Duplicate stock selection.");}}
 private static List<LineRequest>sorted(List<LineRequest>x){return x.stream().sorted(Comparator.comparing(i->i.assetId()!=null?"A"+i.assetId():"B"+i.balanceId())).toList();}private static String fingerprint(CreateRequest r){return hash(r.organizationId()+"|"+r.unitId()+"|"+r.purpose().trim()+"|"+r.startsAt()+"|"+r.endsAt()+"|"+sorted(r.items()));}private OrganizationalUnit selectedUnit(long o,Long id){if(id==null)return null;var u=em.find(OrganizationalUnit.class,id);if(u==null||!u.organization.id.equals(o))bad("Select a unit in the organization.");return u;}private void lockCatalog(){em.createQuery("select c from ItemCategory c order by c.id",ItemCategory.class).setLockMode(LockModeType.PESSIMISTIC_WRITE).getResultList();}private<T>T locked(Class<T>c,Long id){var x=id==null?null:em.find(c,id,LockModeType.PESSIMISTIC_WRITE);if(x==null)bad(c.getSimpleName()+" not found.");return x;}
 private static void notExpired(LocalDate d){if(d!=null&&d.isBefore(LocalDate.now()))bad("Expired stock cannot be reserved.");}private static void amount(BigDecimal v){if(v==null||v.signum()<=0||v.stripTrailingZeros().scale()>4)bad("Quantity must be positive with at most four decimals.");}private static LocalDateTime parse(String v){try{return LocalDateTime.parse(v);}catch(Exception e){bad("Date and time are invalid.");return null;}}private static boolean blank(String v){return v==null||v.isBlank();}private static String term(String v){return"%"+(v==null?"":v.trim().toLowerCase(Locale.ROOT)).replace("!","!!").replace("%","!%").replace("_","!_")+"%";}private static String decimal(BigDecimal v){return v.setScale(4,RoundingMode.UNNECESSARY).toPlainString();}private static void uuid(String v){try{if(v==null||!UUID.fromString(v).toString().equals(v))throw new Exception();}catch(Exception e){bad("A canonical UUID request ID is required.");}}private static String hash(String v){try{return HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256").digest(v.getBytes(StandardCharsets.UTF_8)));}catch(Exception e){throw new IllegalStateException(e);}}private static void bad(String m){throw new ResponseStatusException(HttpStatus.BAD_REQUEST,m);}private static void conflict(String m){throw new ResponseStatusException(HttpStatus.CONFLICT,m);}
}
